package za.ac.cput.domain; import jakarta.persistence.*;
@Entity public class Review{@Id private String reviewId;private String customerId,comments;private int rating; protected Review(){} private Review(Builder b){reviewId=b.reviewId;customerId=b.customerId;comments=b.comments;rating=b.rating;} public String getReviewId(){return reviewId;} public String getCustomerId(){return customerId;} public String getComments(){return comments;} public int getRating(){return rating;} public static class Builder{private String reviewId,customerId,comments;private int rating; public Builder setReviewId(String v){reviewId=v;return this;} public Builder setCustomerId(String v){customerId=v;return this;} public Builder setComments(String v){comments=v;return this;} public Builder setRating(int v){rating=v;return this;} public Builder copy(Review r){reviewId=r.reviewId;customerId=r.customerId;comments=r.comments;rating=r.rating;return this;} public Review build(){return new Review(this);}}}